<div class="alert-summary">
  <div class="card alert-summary__item"><span class="alert-summary__number <?= $suspendedOrganizations ? 'is-warning' : '' ?>"><?= count($suspendedOrganizations) ?></span><div><strong>Suspended organizations</strong><small>Require platform review</small></div></div>
  <div class="card alert-summary__item"><span class="alert-summary__number <?= $inactiveStaff ? 'is-warning' : '' ?>"><?= count($inactiveStaff) ?></span><div><strong>Restricted staff accounts</strong><small>Inactive or suspended</small></div></div>
  <div class="card alert-summary__item"><span class="alert-summary__number is-live"><?= (int) ($onSiteCount ?? 0) ?></span><div><strong>Visitors currently on site</strong><small>Across every location</small></div></div>
