  <div class="card"><div class="card-header"><div><h2>Staff alerts</h2><p>Accounts that cannot currently sign in</p></div><a href="<?= site_url('admin/staff') ?>" class="btn btn-secondary btn-sm">Staff directory</a></div><div class="alert-list">
    <?php if (!$inactiveStaff): ?><div class="empty-state"><div class="empty-state__icon">✓</div><h3>No staff alerts</h3><p>All tenant staff accounts are currently active.</p></div><?php else: foreach ($inactiveStaff as $staff): ?><div class="alert-row"><span class="alert-row__icon alert-row__icon--muted">!</span><span><strong><?= esc($staff['name']) ?></strong><small><?= esc($staff['organization_name'] ?? 'Unassigned') ?></small></span><span class="badge <?= ($staff['status'] ?? '') === 'suspended' ? 'badge-danger' : 'badge-warning' ?>"><?= esc(ucfirst($staff['status'] ?? 'inactive')) ?></span></div><?php endforeach; endif; ?>
  </div></div>
</div>
<div class="card security-alerts"><div class="card-header"><div><h2>Recent security activity</h2><p>Latest sign-ins and account changes recorded platform-wide</p></div><a href="<?= site_url('audit-log') ?>" class="btn btn-secondary btn-sm">Full audit log</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Event</th><th>Action</th><th>When</th><th>IP address</th></tr></thead><tbody>
